    { id: 110, stage: 'regression', points: 10, context: 'starter', prompt: say('$\\bar{x}=2$, $\\bar{y}=9$, $\\sigma_x^2=0{,}5$ eta $\\sigma_{xy}=1$. Zer y estimatzen du Y-ren X-rekiko zuzenak $x=4$ denean?', 'Con $\\bar{x}=2$, $\\bar{y}=9$, $\\sigma_x^2=0{,}5$ y $\\sigma_{xy}=1$, ¿qué y estima la recta de Y sobre X para $x=4$?', 'مع $\\bar{x}=2$ و$\\bar{y}=9$ و$\\sigma_x^2=0{,}5$ و$\\sigma_{xy}=1$، ما قيمة y التي يقدّرها مستقيم Y على X عندما $x=4$؟', 'With $\\bar{x}=2$, $\\bar{y}=9$, $\\sigma_x^2=0{,}5$ and $\\sigma_{xy}=1$, what y does the line of Y on X estimate for $x=4$?'), expected: n(13), hint: same('$m_{yx}=\\frac{1}{0{,}5}=2$'), explanation: same('$9+2\\cdot(4-2)=13$') },
    { id: 111, stage: 'regression', points: 20, context: 'advanced', prompt: say('$\\bar{x}=6$, $\\bar{y}=10$, $\\sigma_y^2=8$ eta $\\sigma_{xy}=-4$. Zer x estimatzen du X-ren Y-rekiko zuzenak $y=14$ denean?', 'Con $\\bar{x}=6$, $\\bar{y}=10$, $\\sigma_y^2=8$ y $\\sigma_{xy}=-4$, ¿qué x estima la recta de X sobre Y para $y=14$?', 'مع $\\bar{x}=6$ و$\\bar{y}=10$ و$\\sigma_y^2=8$ و$\\sigma_{xy}=-4$، ما قيمة x التي يقدّرها مستقيم X على Y عندما $y=14$؟', 'With $\\bar{x}=6$, $\\bar{y}=10$, $\\sigma_y^2=8$ and $\\sigma_{xy}=-4$, what x does the line of X on Y estimate for $y=14$?'), expected: n(4), hint: same('$m_{xy}=\\frac{-4}{8}=-0{,}5$'), explanation: same('$6-0{,}5\\cdot(14-10)=4$') },
    { id: 112, stage: 'regression', points: 30, context: 'master', prompt: say('Erregresio-zuzenak $y=0{,}6x+4$ eta $x=0{,}6y+0{,}8$ dira. Zenbat da $\\bar{y}$?', 'Las rectas de regresión son $y=0{,}6x+4$ y $x=0{,}6y+0{,}8$. ¿Cuánto vale $\\bar{y}$?', 'مستقيما الانحدار هما $y=0{,}6x+4$ و$x=0{,}6y+0{,}8$. كم $\\bar{y}$؟', 'The regression lines are $y=0{,}6x+4$ and $x=0{,}6y+0{,}8$. What is $\\bar{y}$?'), expected: n(7), hint: say('Ebatzi bi zuzenen sistema.', 'Resuelve el sistema de las dos rectas.', 'حلّ نظام المستقيمين.', 'Solve the system of the two lines.'), explanation: same('$\\begin{gathered}x=0{,}6\\,(0{,}6x+4)+0{,}8\\\\ 0{,}64x=3{,}2\\ \\to\\ x=5\\\\ y=0{,}6\\cdot 5+4=7\\end{gathered}$') },

    /* ---------- Full problems ---------- */
    { id: 113, stage: 'problems', points: 10, context: 'starter', prompt: say('$N=5$, $\\sum x=15$, $\\sum y=25$ eta $\\sum xy=85$ badira, zenbat da $\\sigma_{xy}$?', 'Con $N=5$, $\\sum x=15$, $\\sum y=25$ y $\\sum xy=85$, ¿cuánto vale $\\sigma_{xy}$?', 'مع $N=5$ و$\\sum x=15$ و$\\sum y=25$ و$\\sum xy=85$، كم $\\sigma_{xy}$؟', 'With $N=5$, $\\sum x=15$, $\\sum y=25$ and $\\sum xy=85$, what is $\\sigma_{xy}$?'), expected: n(2), hint: same('$\\bar{x}=3\\qquad\\bar{y}=5$'), explanation: same('$\\frac{85}{5}-3\\cdot 5=17-15=2$') },
    { id: 114, stage: 'problems', points: 20, context: 'advanced', prompt: say('Y-ren X-rekiko zuzena $y=0{,}5x+1$ da, $\\sigma_x=4$ eta $\\sigma_y=2{,}5$ izanik. Zenbat da r?', 'La recta de Y sobre X es $y=0{,}5x+1$, con $\\sigma_x=4$ y $\\sigma_y=2{,}5$. ¿Cuánto vale r?', 'مستقيم انحدار Y على X هو $y=0{,}5x+1$، مع $\\sigma_x=4$ و$\\sigma_y=2{,}5$. كم r؟', 'The line of Y on X is $y=0{,}5x+1$, with $\\sigma_x=4$ and $\\sigma_y=2{,}5$. What is r?'), expected: v('0,8'), hint: same('$\\sigma_{xy}=m_{yx}\\,\\sigma_x^2$'), explanation: same('$\\begin{gathered}\\sigma_{xy}=0{,}5\\cdot 4^2=8\\\\ r=\\frac{8}{4\\cdot 2{,}5}=0{,}8\\end{gathered}$') },
    { id: 115, stage: 'problems', points: 30, context: 'master', prompt: say('Y-ren X-rekiko zuzena $y=0{,}8x+2$ da, eta $r=0{,}6$. Zein koefiziente du X-ren Y-rekiko zuzenak?', 'La recta de Y sobre X es $y=0{,}8x+2$ y $r=0{,}6$. ¿Qué coeficiente tiene la recta de X sobre Y?', 'مستقيم انحدار Y على X هو $y=0{,}8x+2$ و$r=0{,}6$. ما معامل مستقيم انحدار X على Y؟', 'The line of Y on X is $y=0{,}8x+2$ and $r=0{,}6$. What coefficient does the line of X on Y have?'), expected: v('0,45'), hint: same('$r^2=m_{yx}\\cdot m_{xy}$'), explanation: same('$m_{xy}=\\frac{0{,}36}{0{,}8}=0{,}45$') }
